/// Converts camelCase or PascalCase to snake_case.
pub fn camel_to_snake(s: Str) -> Str {
  var out = ""
  var i = 0
  for c in s.chars() {
    let code = c.codes().get_or(0, 0)
    if code >= 65 and code <= 90 {
      if i > 0 {
        out = out + "_"
      }
      out = out + c.lower()
    } else {
      out = out + c
    }
    i = i + 1
  }
  return out
}
